import os,subprocess,json
from pathlib import Path
root=Path('/srv/projects')
d={'projects':{},'service_entrypoints':{}}
for p in sorted(root.iterdir()):
 if not p.is_dir() or p.is_symlink():continue
 name=p.name
 def git(*args):
  try:
   q=subprocess.run(['git','-c','safe.directory='+str(p),'-C',str(p),*args],capture_output=True,text=True,timeout=7)
   return {'rc':q.returncode,'out':q.stdout.strip()[:300]}
  except Exception as e:return {'rc':99,'out':''}
 r={'has_git_folder':(p/'.git').exists(),'is_worktree':git('rev-parse','--is-inside-work-tree').get('out')=='true','entrypoints':[]}
 if r['is_worktree']:
  origin=git('config','--get','remote.origin.url').get('out','')
  if '@' in origin and not origin.startswith('git@github.com:'):origin='[private credential URL redacted]'
  r.update({'origin':origin,'head':git('rev-parse','HEAD')['out'],'branch':git('branch','--show-current')['out'],'tracked_changed_count':len(git('status','--porcelain','--untracked-files=no').get('out','').splitlines())})
 for candidate in ('.venv','backend/.venv','node_modules','current','releases','tools/pm2','tools/android-cli-36.0.0','.runtime/npm/rea','vpn/gateway','private','data','backups','.pm2','archive'):
  item=p/candidate
  if item.is_dir() or item.is_symlink():
   r['entrypoints'].append({'path':candidate,'type':'symlink' if item.is_symlink() else 'dir'})
 d['projects'][name]=r
print(json.dumps(d,separators=(',',':')))
